        private static readonly Dictionary<string, string> SemNamespace = CriarSemNamespace();
        private static Dictionary<string, string> CriarSemNamespace()
        {
            var resultado = new Dictionary<string, string>();
            foreach (var item in Campos)
            {
                var partes = item.Key.Split('|');
                var chave = partes[0] + "||" + partes[2];
                string anterior;
                resultado.TryGetValue(chave, out anterior);
                resultado[chave] = anterior + item.Value;
            }
            return resultado;
        }
        internal static bool Aceita(PadraoNFSe padrao, XmlElement raiz)
        {
            string campos;
            if (raiz == null) return false;
            var contratos = raiz.NamespaceURI.Length == 0 ? SemNamespace : Campos;
            if (!contratos.TryGetValue(padrao + "|" + raiz.NamespaceURI + "|" + raiz.LocalName, out campos)) return false;
            foreach (XmlNode child in raiz.ChildNodes)
                if (child is XmlElement && campos.Contains("|" + child.LocalName + "|")) return true;
            return false;
        }
    }
